output_ts = 'import type { POI } from "./poi";\n\nexport const poiExtraColombiaCitiesV2: POI[] = [\n'

for i, c in enumerate(cities):
    id_val = f"{c[0]}-cities-v2"
    typ = "state-capital" if i < 32 else "city"
    output_ts += f"""  {{
    id: "{id_val}",
    type: "{typ}",
    parent: "{c[1]}",
    coords: [{c[2]}, {c[3]}],
    name: {{ de: "{c[4]}", hu: "{c[4]}", ro: "{c[4]}", en: "{c[4]}" }},
    description: {{
      de: "{c[5]}",
      hu: "{c[6]}",
      ro: "{c[7]}",
      en: "{c[8]}"
    }},
    facts: {{
      de: ["{c[9][0]}", "{c[9][1]}"],
      hu: ["{c[10][0]}", "{c[10][1]}"],
      ro: ["{c[11][0]}", "{c[11][1]}"],
      en: ["{c[12][0]}", "{c[12][1]}"]
    }}
  }},\n"""

output_ts += '];\n'

with open('lib/visualLab/data/poiExtraColombiaCitiesV2.ts', 'w', encoding='utf-8') as f:
    f.write(output_ts)
    
print(f"Generated {len(cities)} POIs.")
